List<int> passByDigit(List<int> a, int exp) {
  final buckets = List.generate(10, (_) => <int>[]);
  for (final x in a) {
    buckets[(x ~/ exp) % 10].add(x);
  }
  return [for (final b in buckets) ...b];
}

