List<int> radix(List<int> a) {
  var cur = [...a];
  final mx = cur.reduce((x, y) => x > y ? x : y);
  for (var exp = 1; mx ~/ exp > 0; exp *= 10) {
    final b = List.generate(10, (_) => <int>[]);
    for (final x in cur) {
      b[(x ~/ exp) % 10].add(x);
    }
    cur = [for (final bucket in b) ...bucket];
  }
  return cur;
}

void main() {
  print(radix([329, 457, 657, 839, 436, 720, 355]));
}
