  final a = [2, 0, 1, 2, 0];
  var lo = 0, mid = 0, hi = a.length - 1;
  while (mid <= hi) {
    if (a[mid] == 0) {
      final t = a[lo];
      a[lo++] = a[mid];
      a[mid++] = t;
    } else if (a[mid] == 2) {
      final t = a[hi];
      a[hi--] = a[mid];
      a[mid] = t;
    } else {
      mid++;
    }
  }
  print(a);
}
